    {"from": "ts-seat-service", "to": "ts-travel2-service", "evidence": [{"kind": "trace", "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, approx_quantile(c.duration,0.5)/1e6 callee_med_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id WHERE p.service_name='ts-travel2-service' AND c.service_name='ts-seat-service' GROUP BY 1,2", "claim": "Travel2's calls to seat take about 2.7 s median in the abnormal period."}]},
    {"from": "ts-seat-service", "to": "ts-travel-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, approx_quantile(c.duration,0.5)/1e6 callee_med_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id WHERE p.service_name='ts-travel-plan-service' AND c.service_name='ts-seat-service' GROUP BY 1,2", "claim": "Travel-plan's calls to seat take about 2.6 s median in the abnormal period."}]},
    {"from": "ts-travel-service", "to": "ts-preserve-service", "evidence": [{"kind": "trace", "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, approx_quantile(c.duration,0.5)/1e6 callee_med_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id WHERE p.service_name='ts-preserve-service' AND c.service_name='ts-travel-service' GROUP BY 1,2", "claim": "Preserve's calls to travel take about 5.9 s median in the abnormal period."}]},
    {"from": "ts-travel-service", "to": "ts-route-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, approx_quantile(c.duration,0.5)/1e6 callee_med_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id WHERE p.service_name='ts-route-plan-service' AND c.service_name='ts-travel-service' GROUP BY 1,2", "claim": "Route-plan's calls to travel rise to about 56 ms median, with travel's own latency inflated by seat."}]},
    {"from": "ts-travel2-service", "to": "ts-route-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, approx_quantile(c.duration,0.5)/1e6 callee_med_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id WHERE p.service_name='ts-route-plan-service' AND c.service_name='ts-travel2-service' GROUP BY 1,2", "claim": "Route-plan's calls to travel2 rise to about 33 ms median in the abnormal period."}]},
    {"from": "ts-route-plan-service", "to": "ts-travel-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, approx_quantile(c.duration,0.5)/1e6 callee_med_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id WHERE p.service_name='ts-travel-plan-service' AND c.service_name='ts-route-plan-service' GROUP BY 1,2", "claim": "Travel-plan's calls to route-plan take about 6.5 s median in the abnormal period."}]},
    {"from": "ts-travel-plan-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, approx_quantile(c.duration,0.5)/1e6 callee_med_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id WHERE p.service_name='ts-ui-dashboard' AND c.service_name='ts-travel-plan-service' GROUP BY 1,2", "claim": "Dashboard's calls to travel-plan take about 12.5 s median in the abnormal period."}]},
    {"from": "ts-travel2-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, approx_quantile(c.duration,0.5)/1e6 callee_med_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id WHERE p.service_name='ts-ui-dashboard' AND c.service_name='ts-travel2-service' GROUP BY 1,2", "claim": "Dashboard's calls to travel2 take about 5.6 s median in the abnormal period."}]},
    {"from": "ts-preserve-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, approx_quantile(c.duration,0.5)/1e6 callee_med_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id WHERE p.service_name='ts-ui-dashboard' AND c.service_name='ts-preserve-service' GROUP BY 1,2", "claim": "Dashboard's calls to preserve take about 6.1 s median in the abnormal period."}]}
